use Illuminate\Support\Facades\Schema;

/**
 * Class VibeArcDataSeeder
 *
 * Comprehensive Vibe Arc POS Seeder for Sales Forecasting Research.
 *
 * ==============================================================================
 * RESEARCH INTEGRITY & DATASET PROVENANCE NOTICE:
 * ==============================================================================
 * This seeder contains two clearly distinguished segments:
 *
 * 1. REAL PRODUCTION DATA (2026-04-04 through 2026-09-09):
 *    - Extracted directly from Vibe Arc POS production database export (vibearcpos.sql).
 *    - Preserves exact historical invoices, products, pricelists, food orders,
 *      gaming lounge sessions, payment methods, customer links, and operating expenses.
 *    - 640 real orders, 575 order items, 565 order services, 545 gaming sessions,
 *      620 payments, 110 expenses, 40 products, 9 categories, 7 customers.
 *
 * 2. SYNTHETIC CONTINUATION DATA (2026-09-10 through 2026-09-23):
 *    - Statistically generated and reconciled using empirical bootstrapping from
 *      the observed historical distributions of Vibe Arc POS.
 *    - Purpose: to provide an unbroken, continuous daily time series ending on
 *      2026-09-23 for sales forecasting research and ML evaluation.
 *    - 56 synthetic orders, 50 items, 56 services, 56 gaming sessions,
 *      56 payments, and 12 expenses.
 *    - Strictly bounded to <= 2026-09-23 with deterministic seed (mt_srand(42))
 *      so that `php artisan db:seed --class=VibeArcDataSeeder` produces identical results.
 *
 * ==============================================================================
 * SCHEMA ARCHITECTURE:
 * ==============================================================================
 * Primary schema:
 *   - orders
 *   - order_items
 *   - order_services
 *   - gaming_sessions
 *   - payments
 *   - products
 *   - categories
 *   - customers
 *   - gaming_pool_items
 *   - gaming_pool_pricelist
 *   - expenses
 *
 * Legacy schema compatibility:
 *   - Automatically creates missing tables if running on a clean Laravel database.
 *   - Synchronizes legacy `sales` and `sale_items` tables if present so that
 *     `PredictionService::trainModel()` can execute and evaluate models.
 */
class VibeArcDataSeeder extends Seeder
{
    /**
     * Run the database seeds.
     */
    public function run(): void
    {
        $this->command->info("Starting VibeArcDataSeeder execution...");

        $driver = DB::getDriverName();
        if ($driver === 'mysql') {
            DB::statement('SET FOREIGN_KEY_CHECKS=0;');
        } elseif ($driver === 'sqlite') {
            DB::statement('PRAGMA foreign_keys = OFF;');
        }

        try {
            // Step 1: Ensure required database tables exist
            $this->ensureTablesExist();

            // Step 2: Ensure core roles and users exist safely
            $adminId = $this->setupRolesAndUsers();

            // Step 3: Truncate tables in safe order
            $this->safeTruncateTables();

        // Step 4: Seed Master Catalog Data (Categories, Products, Customers, Units, Pricelist)
        $this->command->info("Seeding master catalog data...");
        $categories = $this->getRealCategories();
        $this->insertCategories($categories);

        $products = $this->getRealProducts();
        $this->insertProducts($products);

        $customers = $this->getRealCustomers();
        $this->insertCustomers($customers);

        if (Schema::hasTable('gaming_pool_pricelist') && !Schema::hasColumn('gaming_pool_pricelist', 'duration')) {
            DB::statement("ALTER TABLE `gaming_pool_pricelist` ADD COLUMN `duration` int UNSIGNED DEFAULT 60;");
        }

        $poolItems = $this->getRealGamingPoolItems();
        $this->insertInChunks('gaming_pool_items', $poolItems);

        $poolPricelist = $this->getRealGamingPoolPricelist();
        $this->insertInChunks('gaming_pool_pricelist', $poolPricelist);

        // Step 5: Insert Historical Real Production Data (2026-04-04 to 2026-09-09)
        $this->command->info("Inserting real production records (2026-04-04 to 2026-09-09)...");
        $realExpenses = $this->getRealExpenses();
        $this->insertExpenses($realExpenses);

        $realOrders = $this->getRealOrders();
        $this->insertInChunks('orders', $realOrders);

        $realOrderItems = $this->getRealOrderItems();
        $this->insertInChunks('order_items', $realOrderItems);

        $realOrderServices = $this->getRealOrderServices();
        $this->insertInChunks('order_services', $realOrderServices);

        $realGamingSessions = $this->getRealGamingSessions();
        $this->insertInChunks('gaming_sessions', $realGamingSessions);

        $realPayments = $this->getRealPayments();
        $this->insertInChunks('payments', $realPayments);

        // Step 6: Generate and Insert Deterministic Synthetic Continuation Data (2026-09-10 to 2026-09-23)
        $this->command->info("Generating synthetic continuation records (2026-09-10 to 2026-09-23)...");
        $syntheticData = $this->generateSyntheticContinuation();

        $this->insertInChunks('orders', $syntheticData['orders']);
        $this->insertInChunks('order_items', $syntheticData['order_items']);
        $this->insertInChunks('order_services', $syntheticData['order_services']);
        $this->insertInChunks('gaming_sessions', $syntheticData['gaming_sessions']);
        $this->insertInChunks('payments', $syntheticData['payments']);
        $this->insertExpenses($syntheticData['expenses']);

        // Combine full dataset for validation & compatibility
        $allOrders = array_merge($realOrders, $syntheticData['orders']);
        $allOrderItems = array_merge($realOrderItems, $syntheticData['order_items']);
        $allOrderServices = array_merge($realOrderServices, $syntheticData['order_services']);
        $allGamingSessions = array_merge($realGamingSessions, $syntheticData['gaming_sessions']);
        $allPayments = array_merge($realPayments, $syntheticData['payments']);
        $allExpenses = array_merge($realExpenses, $syntheticData['expenses']);

        // Step 7: Validate Complete Seeded Dataset
        $this->validateGeneratedData(
            $allOrders,
            $allOrderItems,
            $allOrderServices,
            $allGamingSessions,
            $allPayments,
            $allExpenses
        );

        // Step 8: Backward Compatibility - Synchronize Legacy Sales Tables
        $this->syncLegacySalesTables($allOrders, $allOrderItems, $allPayments, $adminId);

        // Step 9: Trigger ML Training & Predictions
        $this->triggerMlPipeline();

        $this->command->info("VibeArcDataSeeder completed successfully!");
        } finally {
            if ($driver === 'mysql') {
                DB::statement('SET FOREIGN_KEY_CHECKS=1;');
            } elseif ($driver === 'sqlite') {
                DB::statement('PRAGMA foreign_keys = ON;');
            }
        }
    }

