    /**
     * Setup roles and user records safely across schema variations.
     */
    protected function setupRolesAndUsers(): int
    {
        $adminRoleId = 1;
        if (Schema::hasTable('roles')) {
            $adminRole = DB::table('roles')->where('name', 'Admin')->first();
            $adminRoleId = $adminRole->id ?? DB::table('roles')->insertGetId([
                'name' => 'Admin',
                'created_at' => now(),
                'updated_at' => now(),
            ]);
        }

        $userData = [
            'email' => 'admin@vibearc.com',
            'name' => 'Admin User',
            'password' => bcrypt('password'),
            'created_at' => now(),
            'updated_at' => now(),
        ];
        if (Schema::hasColumn('users', 'username')) {
            $userData['username'] = 'admin';
        }
        if (Schema::hasColumn('users', 'role_id')) {
            $userData['role_id'] = $adminRoleId;
        }
        if (Schema::hasColumn('users', 'is_active')) {
            $userData['is_active'] = 1;
        }

        $admin = User::firstOrCreate(['email' => 'admin@vibearc.com'], $userData);
        if (method_exists($admin, 'assignRole') && Schema::hasTable('roles') && DB::table('roles')->where('name', 'Admin')->exists()) {
            try { $admin->assignRole('Admin'); } catch (\Throwable $e) {}
        }

        return $admin->id ?? 1;
    }

    /**
     * Disable FK checks and truncate tables cleanly.
     */
    protected function safeTruncateTables(): void
    {
        $driver = DB::getDriverName();
        if ($driver === 'mysql') {
            DB::statement('SET FOREIGN_KEY_CHECKS=0;');
        } elseif ($driver === 'sqlite') {
            DB::statement('PRAGMA foreign_keys = OFF;');
        }

        $tables = [
            'gaming_sessions',
            'order_services',
            'payments',
            'order_items',
            'orders',
            'sale_items',
            'sales',
            'sales_predictions',
            'audit_logs',
            'gaming_pool_pricelist',
            'gaming_pool_items',
            'expenses',
            'products',
            'categories',
            'customers',
        ];

        foreach ($tables as $t) {
            if (Schema::hasTable($t)) {
                DB::table($t)->truncate();
            }
        }
    }

    /**
     * Insert categories with schema adaptation.
     */
    protected function insertCategories(array $categories): void
    {
        $hasType = Schema::hasColumn('categories', 'type');
        $hasIsActive = Schema::hasColumn('categories', 'is_active');

        $rows = [];
        foreach ($categories as $c) {
            $row = [
                'id' => $c['id'],
                'name' => $c['name'],
                'created_at' => $c['created_at'] ?? now(),
                'updated_at' => $c['updated_at'] ?? now(),
            ];
            if ($hasType) {
                $row['type'] = $c['type'] ?? 'food';
                $row['created_by'] = $c['created_by'] ?? 1;
            }
            if ($hasIsActive) {
                $row['is_active'] = 1;
            }
            $rows[] = $row;
        }

        DB::table('categories')->insert($rows);
    }

    /**
     * Insert products with schema adaptation.
     */
    protected function insertProducts(array $products): void
    {
        $hasSellingPrice = Schema::hasColumn('products', 'selling_price');
        $hasPrice = Schema::hasColumn('products', 'price');

        $categoryFallback = function($name, $catId) {
            if ($catId !== null && $catId > 0) return $catId;
            $nl = strtolower($name);
            if (str_contains($nl, 'burger') || str_contains($nl, 'submarine') || str_contains($nl, 'hot dog')) return 4;
            if (str_contains($nl, 'milkshake') || str_contains($nl, 'faluda') || str_contains($nl, 'milo')) return 1;
            if (str_contains($nl, 'mojito') || str_contains($nl, 'juice')) return 2;
            if (str_contains($nl, 'tea') || str_contains($nl, 'coffee')) return 3;
            if (str_contains($nl, 'fries') || str_contains($nl, 'nugget') || str_contains($nl, 'roll') || str_contains($nl, 'cutlet') || str_contains($nl, 'patties') || str_contains($nl, 'add on')) return 5;
            if (str_contains($nl, 'pepsi') || str_contains($nl, 'seven up') || str_contains($nl, 'water') || str_contains($nl, 'drink')) return 6;
            return 4;
        };

        $rows = [];
        foreach ($products as $p) {
            $catId = $categoryFallback($p['name'], $p['category_id']);
            $row = [
                'id' => $p['id'],
                'name' => $p['name'],
                'category_id' => $catId,
                'created_at' => $p['created_at'] ?? now(),
                'updated_at' => $p['updated_at'] ?? now(),
            ];
            if ($hasSellingPrice) {
                $row['cost_price'] = $p['cost_price'] ?? null;
                $row['selling_price'] = (float)$p['selling_price'];
                $row['pickme_price'] = (float)($p['pickme_price'] ?? $p['selling_price']);
                $row['uber_price'] = (float)($p['uber_price'] ?? $p['selling_price']);
                $row['preparation_type'] = $p['preparation_type'] ?? 'kitchen';
                $row['discount'] = (float)($p['discount'] ?? 0);
            }
            if ($hasPrice) {
                $row['price'] = (float)$p['selling_price'];
                $row['cost'] = $p['cost_price'] ? (float)$p['cost_price'] : 0.00;
                $row['is_active'] = 1;
                $row['sku'] = 'PRD-' . str_pad($p['id'], 4, '0', STR_PAD_LEFT);
            }
            $rows[] = $row;
        }

        DB::table('products')->insert($rows);
    }

    /**
     * Insert customers with schema adaptation.
     */
    protected function insertCustomers(array $customers): void
    {
        $hasCreatedBy = Schema::hasColumn('customers', 'created_by');

        $rows = [];
        foreach ($customers as $c) {
            $row = [
                'id' => $c['id'],
                'name' => $c['name'],
                'phone' => $c['phone'] ?? null,
                'email' => $c['email'] ?? null,
                'created_at' => $c['created_at'] ?? now(),
                'updated_at' => $c['updated_at'] ?? now(),
            ];
            if ($hasCreatedBy) {
                $row['created_by'] = $c['created_by'] ?? 1;
            }
            $rows[] = $row;
        }

        DB::table('customers')->insert($rows);
    }

    /**
     * Insert expenses with schema adaptation.
     */
    protected function insertExpenses(array $expenses): void
    {
        $hasExpenseDate = Schema::hasColumn('expenses', 'expense_date');
        $hasDate = Schema::hasColumn('expenses', 'date');

        $rows = [];
        foreach ($expenses as $e) {
            $row = [
                'id' => $e['id'],
                'amount' => (float)$e['amount'],
                'created_at' => $e['created_at'] ?? now(),
                'updated_at' => $e['updated_at'] ?? now(),
            ];
            $desc = !empty($e['description']) ? $e['description'] : ($e['name'] ?? 'General expense');
            if ($hasExpenseDate) {
                $row['name'] = $e['name'];
                $row['expense_date'] = $e['expense_date'];
                $row['description'] = $desc;
            }
            if ($hasDate) {
                $row['category'] = $e['name'] ?? 'Other';
                $row['date'] = $e['expense_date'];
                $row['description'] = $desc;
                $row['user_id'] = 1;
            }
            $rows[] = $row;
        }

        foreach (array_chunk($rows, 100) as $chunk) {
            DB::table('expenses')->insert($chunk);
        }
    }

    /**
     * Helper to insert records in safe batches.
     */
    protected function insertInChunks(string $table, array $rows, int $chunkSize = 100): void
    {
        if (!Schema::hasTable($table) || empty($rows)) {
            return;
        }

        $tableCols = array_flip(Schema::getColumnListing($table));

        $filtered = array_map(function ($row) use ($tableCols, $table) {
            $r = array_intersect_key($row, $tableCols);
            if ($table === 'order_items') {
                if (!isset($r['subtotal']) || $r['subtotal'] === null) {
                    $unit = (float)($row['unit_price'] ?? $row['applied_price'] ?? $row['original_price'] ?? $row['final_amount'] ?? 0);
                    $qty = (int)($row['quantity'] ?? 1);
                    $r['subtotal'] = $unit * $qty;
                }
                if (!isset($r['final_amount']) || $r['final_amount'] === null) {
                    $r['final_amount'] = $r['subtotal'];
                }
            }
            if ($table === 'order_services') {
                if (!isset($r['subtotal']) || $r['subtotal'] === null) {
                    $r['subtotal'] = (float)($row['final_amount'] ?? 0);
                }
                if (!isset($r['final_amount']) || $r['final_amount'] === null) {
                    $r['final_amount'] = $r['subtotal'];
                }
            }
            if ($table === 'payments') {
                if (isset($tableCols['sale_id']) && (!isset($r['sale_id']) || $r['sale_id'] === null)) {
                    $r['sale_id'] = $row['order_id'] ?? $row['id'];
                }
                if (isset($tableCols['method']) && (!isset($r['method']) || $r['method'] === null)) {
                    $pt = $row['payment_type'] ?? 'cash';
                    $r['method'] = in_array($pt, ['cash', 'card']) ? $pt : 'digital';
                }
                if (isset($tableCols['amount']) && (!isset($r['amount']) || $r['amount'] === null)) {
                    $r['amount'] = (float)($row['total_amount'] ?? 0);
                }
                if (isset($tableCols['reference']) && (!isset($r['reference']) || $r['reference'] === null)) {
                    $r['reference'] = 'PAY-' . str_pad($row['id'], 6, '0', STR_PAD_LEFT);
                }
            }
            return $r;
        }, $rows);

        foreach (array_chunk($filtered, $chunkSize) as $chunk) {
            DB::table($table)->insert($chunk);
        }
    }

