    /**
     * Helper to generate synthetic orders for a specific date using empirical patterns.
     */
    public function generateOrdersForDate(
        string $date,
        int $orderCount,
        array $patterns,
        array &$orders,
        array &$orderItems,
        array &$orderServices,
        array &$gamingSessions,
        array &$payments,
        int &$nextOrderId,
        int &$nextItemId,
        int &$nextServiceId,
        int &$nextSessionId,
        int &$nextPaymentId
    ): void {
        $times = [
            ['02:50:48', '06:14:05', '08:55:17', '11:16:38', '11:17:46', '12:05:00', '12:45:00'],
            ['03:15:00', '07:40:00', '08:38:07', '10:15:30', '11:22:15', '12:10:00', '12:50:00'],
        ];

        for ($i = 0; $i < $orderCount; $i++) {
            $orderId = $nextOrderId++;
            $invoiceNumber = 'VAC/' . str_replace('-', '', $date) . '/' . str_pad($i + 1, 4, '0', STR_PAD_LEFT);
            $timeSet = $times[$i % 2];
            $time = $timeSet[$i % count($timeSet)];
            $createdAt = "$date $time";

            $orderType = 'mixed';
            $saleSource = ($i === 0 && ($date === '2026-09-12' || $date === '2026-09-20')) ? 'pickme' : 'normal';

            $orders[] = [
                'id' => $orderId,
                'invoice_number' => $invoiceNumber,
                'order_type' => $orderType,
                'sale_source' => $saleSource,
                'status' => 'completed',
                'user_id' => 1,
                'customer_id' => null,
                'created_at' => $createdAt,
                'updated_at' => $createdAt,
            ];

            // Generate order items (food) for ~85% of orders
            $itemsTotal = 0.0;
            if ($i % 7 !== 6) {
                $itemsTotal = $this->generateOrderItems($orderId, $orderType, $createdAt, $patterns, $orderItems, $nextItemId);
            }

            // Generate gaming services / sessions
            $servicesTotal = $this->generateGamingSession($orderId, $orderType, $createdAt, $patterns, $orderServices, $gamingSessions, $nextServiceId, $nextSessionId);

            // Calculate order totals & discount
            $orderCalc = $this->calculateRealisticOrderValue($itemsTotal, $servicesTotal, $patterns);

            // Generate payment record
            $this->generatePayment($orderId, $orderType, $saleSource, $orderCalc['total_amount'], $orderCalc['discount'], $createdAt, $payments, $nextPaymentId);
        }
    }

    /**
     * Helper to generate food/drink order items.
     */
    public function generateOrderItems(
        int $orderId,
        string $orderType,
        string $createdAt,
        array $patterns,
        array &$orderItems,
        int &$nextItemId
    ): float {
        static $productWeighted = null;
        if ($productWeighted === null) {
            $productWeighted = [];
            foreach ($patterns['popular_products'] as $pid => $info) {
                for ($w = 0; $w < $info['weight']; $w++) $productWeighted[] = $pid;
            }
        }

        $pid = $productWeighted[mt_rand(0, count($productWeighted) - 1)];
        $pInfo = $patterns['popular_products'][$pid];
        $qty = 1;
        $unitPrice = (float)$pInfo['price'];
        $itemSubtotal = $unitPrice * $qty;

        $orderItems[] = [
            'id' => $nextItemId++,
            'order_id' => $orderId,
            'product_id' => $pid,
            'quantity' => $qty,
            'subtotal' => $itemSubtotal,
            'discount_percentage' => 0.00,
            'discount_amount' => 0.00,
            'final_amount' => $itemSubtotal,
            'unit_price' => $unitPrice,
            'applied_price' => $unitPrice,
            'ticket_type' => 'KOT',
            'status' => 'done',
            'original_price' => $unitPrice,
            'price_type' => 'normal',
            'created_at' => $createdAt,
            'updated_at' => $createdAt,
        ];

        return $itemSubtotal;
    }

    /**
     * Helper to generate gaming session and linked order service.
     */
    public function generateGamingSession(
        int $orderId,
        string $orderType,
        string $createdAt,
        array $patterns,
        array &$orderServices,
        array &$gamingSessions,
        int &$nextServiceId,
        int &$nextSessionId
    ): float {
        static $pricelistWeighted = null;
        if ($pricelistWeighted === null) {
            $pricelistWeighted = [];
            foreach ($patterns['popular_pricelists'] as $plid => $info) {
                for ($w = 0; $w < $info['weight']; $w++) $pricelistWeighted[] = $plid;
            }
        }

        $plid = $pricelistWeighted[mt_rand(0, count($pricelistWeighted) - 1)];
        $plInfo = $patterns['popular_pricelists'][$plid];
        $price = (float)$plInfo['price'];
        $unitId = (int)$plInfo['unit_id'];
        $duration = (int)$plInfo['duration'];

        $startTime = Carbon::parse($createdAt);
        $endTime = $startTime->copy()->addMinutes($duration);

        $serviceId = $nextServiceId++;
        $orderServices[] = [
            'id' => $serviceId,
            'order_id' => $orderId,
            'price_list_id' => $plid,
            'start_time' => $startTime->toDateTimeString(),
            'end_time' => $endTime->toDateTimeString(),
            'duration_minutes' => $duration,
            'extra_controller_count' => 0,
            'extra_controller_total' => 0.00,
            'subtotal' => $price,
            'discount_amount' => 0.00,
            'final_amount' => $price,
            'status' => 'completed',
            'created_at' => $createdAt,
            'updated_at' => $createdAt,
        ];

        $gamingSessions[] = [
            'id' => $nextSessionId++,
            'unit_id' => $unitId,
            'order_id' => $orderId,
            'order_service_id' => $serviceId,
            'started_by' => 1,
            'ended_by' => 1,
            'start_time' => $startTime->toDateTimeString(),
            'end_time' => $endTime->toDateTimeString(),
            'duration_minutes' => $duration,
            'status' => 'completed',
            'created_at' => $createdAt,
            'updated_at' => $createdAt,
        ];

        return $price;
    }

    /**
     * Helper to calculate realistic order value with empirical discounts.
     */
    public function calculateRealisticOrderValue(float $itemsTotal, float $servicesTotal, array $patterns): array
    {
        $gross = $itemsTotal + $servicesTotal;
        $discCandidate = (float)$patterns['discounts'][mt_rand(0, count($patterns['discounts']) - 1)];
        $discount = min($discCandidate, max(0.0, $gross - 200.0));
        $net = max(100.0, $gross - $discount);

        return [
            'gross' => $gross,
            'discount' => $discount,
            'total_amount' => $net,
        ];
    }

