    /**
     * Comprehensive validation of the complete seeded dataset.
     */
    public function validateGeneratedData(
        array $orders,
        array $orderItems,
        array $orderServices,
        array $gamingSessions,
        array $payments,
        array $expenses
    ): void {
        $this->command->info("\n--- DATA QUALITY & RESEARCH VALIDATION REPORT ---");

        // 1. Date range
        $orderDates = array_map(fn($o) => substr($o['created_at'], 0, 10), $orders);
        $minDate = min($orderDates);
        $maxDate = max($orderDates);
        $distinctDays = count(array_unique($orderDates));

        $this->command->info("1. Date Range Coverage:");
        $this->command->info("   - Minimum Order Date : $minDate");
        $this->command->info("   - Maximum Order Date : $maxDate");
        $this->command->info("   - Required End Date  : 2026-09-23 (Match: " . ($maxDate === '2026-09-23' ? 'PASS' : 'FAIL') . ")");
        $this->command->info("   - Distinct Active Days: $distinctDays days");

        // 2. Record counts
        $this->command->info("2. Record Counts:");
        $this->command->info("   - Total Orders         : " . count($orders));
        $this->command->info("   - Total Order Items    : " . count($orderItems));
        $this->command->info("   - Total Order Services : " . count($orderServices));
        $this->command->info("   - Total Gaming Sessions: " . count($gamingSessions));
        $this->command->info("   - Total Payments       : " . count($payments));
        $this->command->info("   - Total Expenses       : " . count($expenses));

        // 3. Foreign key referential integrity
        $orderIdMap = array_flip(array_column($orders, 'id'));
        $paymentOrderIds = array_column($payments, 'order_id');
        $orphanPayments = count(array_filter($paymentOrderIds, fn($id) => !isset($orderIdMap[$id])));

        $itemOrderIds = array_column($orderItems, 'order_id');
        $orphanItems = count(array_filter($itemOrderIds, fn($id) => !isset($orderIdMap[$id])));

        $serviceOrderIds = array_column($orderServices, 'order_id');
        $orphanServices = count(array_filter($serviceOrderIds, fn($id) => !isset($orderIdMap[$id])));

        $sessionOrderIds = array_filter(array_column($gamingSessions, 'order_id'));
        $orphanSessions = count(array_filter($sessionOrderIds, fn($id) => !isset($orderIdMap[$id])));

        $this->command->info("3. Referential Integrity Check:");
        $this->command->info("   - Orphan Payments       : $orphanPayments (" . ($orphanPayments === 0 ? 'PASS' : 'FAIL') . ")");
        $this->command->info("   - Orphan Order Items    : $orphanItems (" . ($orphanItems === 0 ? 'PASS' : 'FAIL') . ")");
        $this->command->info("   - Orphan Order Services : $orphanServices (" . ($orphanServices === 0 ? 'PASS' : 'FAIL') . ")");
        $this->command->info("   - Orphan Gaming Sessions: $orphanSessions (" . ($orphanSessions === 0 ? 'PASS' : 'FAIL') . ")");

        // 4. Duplicate checks
        $this->command->info("4. Primary Key Uniqueness Check:");
        $orderDupes = count($orders) - count(array_unique(array_column($orders, 'id')));
        $payDupes = count($payments) - count(array_unique(array_column($payments, 'id')));
        $itemDupes = count($orderItems) - count(array_unique(array_column($orderItems, 'id')));
        $this->command->info("   - Duplicate Order IDs   : $orderDupes (" . ($orderDupes === 0 ? 'PASS' : 'FAIL') . ")");
        $this->command->info("   - Duplicate Payment IDs : $payDupes (" . ($payDupes === 0 ? 'PASS' : 'FAIL') . ")");
        $this->command->info("   - Duplicate Item IDs    : $itemDupes (" . ($itemDupes === 0 ? 'PASS' : 'FAIL') . ")");

        // 5. Daily coverage around the seam (September 2026)
        $this->command->info("5. September Continuous Daily Series (Seam & Extension Check):");
        $dailyCounts = [];
        $dailyRevenues = [];
        foreach ($payments as $p) {
            $d = substr($p['created_at'], 0, 10);
            $dailyCounts[$d] = ($dailyCounts[$d] ?? 0) + 1;
            $dailyRevenues[$d] = ($dailyRevenues[$d] ?? 0) + (float)$p['total_amount'];
        }

        for ($t = strtotime('2026-09-08'); $t <= strtotime('2026-09-23'); $t += 86400) {
            $d = date('Y-m-d', $t);
            $c = $dailyCounts[$d] ?? 0;
            $r = $dailyRevenues[$d] ?? 0.0;
            $label = ($d <= '2026-09-09') ? 'REAL' : 'SYNTHETIC';
            $this->command->info(sprintf("   - %s (%s) [%9s]: %2d orders | Rs. %8.2f", $d, date('D', $t), $label, $c, $r));
        }
    }

    /**
     * Synchronize legacy sales and sale_items tables for backward compatibility
     * with the sales forecasting ML pipeline.
     */
    protected function syncLegacySalesTables(array $orders, array $orderItems, array $payments, int $adminId): void
    {
        if (!Schema::hasTable('sales')) {
            return;
        }

        $this->command->info("Synchronizing legacy `sales` and `sale_items` tables for forecasting pipeline...");

        $paymentMap = [];
        foreach ($payments as $p) {
            $paymentMap[$p['order_id']] = $p;
        }

        $itemsMap = [];
        foreach ($orderItems as $item) {
            $itemsMap[$item['order_id']][] = $item;
        }

        $salesRows = [];
        $saleItemsRows = [];
        $paymentLegacyRows = [];
        $hasLegacyPayments = Schema::hasTable('payments') && Schema::hasColumn('payments', 'sale_id');

        $itemIdCounter = 1;
        $payIdCounter = 1;

        foreach ($orders as $o) {
            $orderId = $o['id'];
            $pay = $paymentMap[$orderId] ?? null;
            $discount = $pay ? (float)$pay['discount'] : 0.0;
            $total = $pay ? (float)$pay['total_amount'] : 0.0;
            $payType = $pay['payment_type'] ?? 'cash';
            $method = in_array($payType, ['cash', 'card']) ? $payType : 'digital';

            $salesRows[] = [
                'id' => $orderId,
                'invoice_number' => $o['invoice_number'],
                'customer_id' => $o['customer_id'] ?? null,
                'user_id' => $adminId,
                'subtotal' => $total + $discount,
                'discount_amount' => $discount,
                'tax_amount' => 0.00,
                'total' => $total,
                'status' => 'completed',
                'order_type' => ($o['order_type'] === 'takeaway') ? 'takeaway' : 'dine_in',
                'notes' => 'VibeArc Order ' . $o['invoice_number'],
                'created_at' => $o['created_at'],
                'updated_at' => $o['updated_at'],
            ];

            if (isset($itemsMap[$orderId])) {
                foreach ($itemsMap[$orderId] as $it) {
                    $saleItemsRows[] = [
                        'id' => $itemIdCounter++,
                        'sale_id' => $orderId,
                        'product_id' => $it['product_id'],
                        'quantity' => $it['quantity'],
                        'unit_price' => (float)$it['unit_price'],
                        'discount' => (float)($it['discount_amount'] ?? 0),
                        'total' => (float)$it['subtotal'],
                        'total_price' => (float)$it['subtotal'],
                        'created_at' => $it['created_at'],
                        'updated_at' => $it['updated_at'],
                    ];
                }
            }
        }

        $this->insertInChunks('sales', $salesRows);
        $this->insertInChunks('sale_items', $saleItemsRows);

        $this->command->info("Legacy sales synchronization complete: " . count($salesRows) . " sales rows created.");
    }

    /**
     * Trigger ML service model training and prediction generation.
     */
    protected function triggerMlPipeline(): void
    {
        try {
            /** @var PredictionService $predictionService */
            $predictionService = app(PredictionService::class);
            $this->command->info("Triggering ML training on VibeArc sales dataset...");
            $trained = $predictionService->trainModel();
            if ($trained) {
                $this->command->info("ML model successfully trained!");
                $predictionService->fetchPredictions();
                $this->command->info("Forecast predictions generated!");
            } else {
                $this->command->warn("ML service returned false (ensure FastAPI is running on port 8001).");
            }
        } catch (\Throwable $e) {
            $this->command->warn("ML Service: " . $e->getMessage());
        }
    }

